"""Generate glTF consumer QA notes from ignored validation results/preview statistics."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT/'extract/gltf'


def main():
    result = json.loads((OUT/'skin-validation.json').read_text())
    rows = ['# glTF consumer and visual checks (generated)','',
            'Generated by `uv run --offline python tools/codex/report_gltf_qa.py` from actual exported-file preview results.', '',
            '`python tools/codex/preview_gltf.py extract/gltf/008_0000BC/actor.gltf --clip set0_state05_run` '
            'renders a PNG contact sheet using the installed system Python/numpy (the uv environment does not contain numpy). '
            'The consumer reads the emitted glTF JSON, binary accessors, PNG texture pages, node transforms, animation samplers, '
            'joint indices, weights and inverse-bind matrices. No renderer dependencies are installed; no network/server/browser is used.', '',
            'Each contact sheet has front, side, rear rows; columns sample the selected clip from start to end. '
            'Quaternion tracks use shortest-path SLERP. Colours/textures are shown as unlit base colour with glTF sRGB texture conversion; '
            'PSX lighting, environment mapping and translucent blending are outside this preview. '
            'The preview expects the exporter\'s RGBA PNG filter-0 output and is not a general-purpose glTF renderer.', '',
            '## Full skinning regression','',
            '`python tools/codex/check_preview.py` checks every model in bind pose plus first/middle/last keys of every resolved clip. '
            'It compares the actual consumed inverse-bind/joint/weight output with export_model.posed_positions for raw poses and independent channel TRS matrices; '
            'source local vertices are not substituted into the consumer.', '',
            f'- Models: {result["models"]}',
            f'- Clip keys: {result["clip_keys"]}',
            f'- Emitted corner positions compared: {result["corner_positions_compared"]}',
            f'- Maximum error: {result["max_error"]:.9g} export units (threshold 2e-5).', '',
            '## Contact sheet inventory','',
            'Visual inspection of the generated Spike stand/run sheets shows coherent body/limb poses, red hair, face, blue shorts and boots. '
            'Monkey and area 0x44 actor sheets also show coherent poses and texture placement. '
            'The corrected idle clip intentionally starts with zero root scale, collapsing all geometry; blank samples are accepted only when the consumed vertices demonstrably collapse to one point. These are inspection findings, not runtime/gameplay verification.', '',
            '| Model | Clip | Duration (seconds at export fps) | Samples | Minimum visible pixels | Image (gitignored) |',
            '|---|---|---|---|---|---|']
    n = 0
    for file in sorted(OUT.glob('*/preview_*.json')):
        r = json.loads(file.read_text())
        png = file.with_suffix('.png')
        relative = png.relative_to(ROOT).as_posix()
        rows.append(f'| {file.parent.name} | {r["clip"]} | {r["duration_seconds"]:.5g} | {r["samples"]} | '
                    f'{min(f["visible_pixels"] for f in r["frames"])} | [{png.name}](../{relative}) |')
        n += 1
    (ROOT/'notes/53-gltf-visual-qa.md').write_text('\n'.join(rows)+'\n',encoding='utf-8')
    print(f'QA notes: {n} sheets; {result["models"]} models / {result["clip_keys"]} animation keys checked')


if __name__ == '__main__':
    main()
